def document(name, texts, *, title='Independent witness', library='alpha', card=False, approved=True):
    return {'doc_id': name, 'path': f'{library}/{name}.md', 'title': title, 'status': 'canonical' if approved else 'draft', 'authority_state': 'approved' if approved else 'unreviewed', 'canonical_layer': 'canonical' if approved else 'supporting', 'corpus_class': 'CORPUS_CLASS:CANON', 'project': 'Candidate diagnostics', 'epistemic_last_evaluated': '2026-10-21T12:00:00+00:00', 'epistemic_valid_until': '2030-01-01T00:00:00+00:00', 'plane_card': {'plane': 'canonical', 'non_authoritative': not approved, 'confidence': 0.98, 'valid_until': '2030-01-01T00:00:00+00:00'} if card else None, 'chunks': [{'chunk_id': f'{name}:{i}', 'chunk_index': i, 'heading_path': 'Evidence', 'chunk_type': 'body', 'text': text} for i, text in enumerate(texts)]}
